css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .52); position: relative; }
.loader .pad { position: absolute; bottom: 6%; width: 26%; height: 18%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 55%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 40%, transparent); }
.loader .pad:nth-of-type(1) { left: 2%; }
.loader .pad:nth-of-type(2) { left: 37%; }
.loader .pad:nth-of-type(3) { left: 72%; }
.loader .frog { position: absolute; left: 7%; bottom: 14%; width: 16%; height: 30%; border-radius: 46% 46% 40% 40%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent)); animation: frog-hop calc(var(--loader-speed) * 2.4) cubic-bezier(.4, 0, .5, 1) infinite; }
.loader .eye { position: absolute; top: -14%; width: 34%; height: 34%; border-radius: 50%; background: var(--accent-2); box-shadow: inset 0 -2px 0 color-mix(in srgb, #000 20%, transparent); }
.loader .eye::after { content: ''; position: absolute; left: 26%; top: 30%; width: 40%; height: 40%; border-radius: 50%; background: #0f172a; }
.loader .eye:nth-of-type(1) { left: 8%; }
.loader .eye:nth-of-type(2) { right: 8%; }
@keyframes frog-hop { 0%, 10% { transform: translate(0, 0) scaleY(1); } 16% { transform: translate(0, 8%) scaleY(.78); } 30% { transform: translate(110%, -120%) scaleY(1.12); } 42%, 52% { transform: translate(219%, 0) scaleY(1); } 58% { transform: translate(219%, 8%) scaleY(.78); } 72% { transform: translate(329%, -120%) scaleY(1.12); } 84%, 94% { transform: translate(438%, 0) scaleY(1); } 100% { transform: translate(0, 0) scaleY(1); } }
